def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Spread a row's single colored seed horizontally across the open area.
    for r in range(h):
        seeds = [c for c in range(w) if g[r][c] not in (0, 5)]
        if len(seeds) == 1:
            c = seeds[0]
            # Extend toward the nearest vertical 5 divider, if present.
            dividers = [x for x in range(c + 1, w) if g[r][x] == 5]
            end = min(dividers) if dividers else w
            for x in range(c + 1, end):
                if g[r][x] == 0:
                    g[r][x] = g[r][c]

    # A vertical 5 divider can carry a one- or multi-row colored motif
    # upward/downward along its length.
    for c in range(w):
        rows5 = [r for r in range(h) if g[r][c] == 5]
        if len(rows5) < 3:
            continue
        top, bottom = min(rows5), max(rows5)
        right = c + 1
        if right >= w:
            continue
        motif_rows = [r for r in range(h)
                      if any(g[r][x] not in (0, 5) for x in range(right, w))]
        if not motif_rows:
            continue
        # Use the colored rows nearest the lower end of the divider as motif.
        motif_rows = sorted(motif_rows)
        motif_rows = motif_rows[-2:] if len(motif_rows) >= 2 else motif_rows
        motif = [[g[r][x] for x in range(right, w)] for r in motif_rows]
        start = min(motif_rows)
        for r in range(top, bottom + 1):
            if r in motif_rows:
                continue
            pattern = motif[(r - start) % len(motif)]
            for j, x in enumerate(range(right, w)):
                if g[r][x] == 0:
                    g[r][x] = pattern[j]

    return g
