def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A horizontal 5-bar marks the width of rows to fill from seeds
    # directly below its left end.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            b = c - 1
            if b > a:
                for rr in range(r + 1, h):
                    color = grid[rr][a]
                    if color not in (0, 5):
                        for x in range(a, b + 1):
                            if g[rr][x] == 0:
                                g[rr][x] = color

    # A vertical 5-bar marks the height over which a motif to its right
    # is repeated.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            b = r - 1
            if b <= a or c + 1 >= w:
                continue

            motif_rows = [
                rr for rr in range(a, b + 1)
                if any(grid[rr][x] not in (0, 5) for x in range(c + 1, w))
            ]
            if not motif_rows:
                continue

            left = c + 1
            while left < w and all(grid[rr][left] == 0 for rr in motif_rows):
                left += 1
            right = w
            while right > left and all(grid[rr][right - 1] == 0 for rr in motif_rows):
                right -= 1

            motif = [[grid[rr][x] for x in range(left, right)]
                     for rr in motif_rows]
            first = motif_rows[0]
            for rr in range(a, b + 1):
                pattern = motif[(rr - first) % len(motif)]
                for j, x in enumerate(range(left, right)):
                    if g[rr][x] == 0:
                        g[rr][x] = pattern[j]

    return g
